import { createRequire } from 'node:module';
import { readFile, writeFile } from 'node:fs/promises';
const root = process.cwd();
const require = createRequire(root + '/package.json');
const { build } = require(createRequire(require.resolve('vite')).resolve('esbuild'));
const { chromium } = require('playwright');
const bundle = await build({ stdin: { contents: `export { measureStoryScoreScenes } from './src/components/story-score/measurement'; export { measureProjectsHorizontalCandidate } from './src/components/story-score/projects-capacity-candidate';`, resolveDir: root, loader: 'ts' }, bundle: true, write: false, platform: 'browser', format: 'iife', globalName: 'visit3Diagnostic', alias: { '@': root + '/src' }, plugins:[{name:'observe-only',setup(b){b.onLoad({filter:/measurement\.ts$/},async({path})=>({contents:(await readFile(path,'utf8')).replace('  return Object.freeze({\n    measurements,', '  globalThis.__visit3Observed?.(track, measurements);\n  return Object.freeze({\n    measurements,'),loader:'ts'}))}}]});
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1536,height:900}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
try {
 await page.goto('http://127.0.0.1:3107/__visual-lab/story/motion');
 await page.waitForFunction(()=>document.querySelector('main[data-motion-lab]')?.dataset.motionProjectsCapacity==='INSUFFICIENT_CAPACITY');
 await page.evaluate(()=>document.fonts.ready);
 await page.addScriptTag({content:bundle.outputFiles[0].text});
 const capture=await page.evaluate(async()=>{
  const root=document.querySelector('main[data-motion-lab]');
  const shape=r=>({x:r.x,y:r.y,width:r.width,height:r.height});
  const raw=(item,track)=>{ const link=item.querySelector('a'),s=getComputedStyle(item),ls=getComputedStyle(link),tr=track.getBoundingClientRect();return {item:shape(item.getBoundingClientRect()),link:shape(link.getBoundingClientRect()),track:shape(tr),width:s.width,height:s.height,origin:s.transformOrigin,transform:s.transform,outlineWidth:ls.outlineWidth,outlineOffset:ls.outlineOffset,outlineStyle:ls.outlineStyle,focusVisible:link.matches(':focus-visible'),borderRadius:ls.borderRadius,animations:item.getAnimations().map(a=>({time:a.currentTime,state:a.playState})),itemOffset:[item.offsetLeft,item.offsetTop,item.offsetWidth,item.offsetHeight]};};
  let candidate;
  window.__visit3Observed=(track,measurements)=>{if(track.closest('[data-projects-capacity-host]')) candidate={measurements,raw:[...track.querySelectorAll('[data-project-card-item]')].map(i=>raw(i,track))};};
  let result;
  result=visit3Diagnostic.measureProjectsHorizontalCandidate(root,1536,900,'visit3-classification');
  // Diagnostic mode forcing only after stopping the existing driver; never a production eligibility change.
  window.__WFLYER_PHASE5_MOTION__.destroyForReplacement();
  await new Promise(r=>setTimeout(r,500));
  root.dataset.projectionMode='horizontal-enhanced';
  const track=root.querySelector('[data-motion-track]');
  track.style.transform='none';
  const liveIdle=[...track.querySelectorAll('[data-project-card-item]')].map(i=>raw(i,track));
  const live={...visit3Diagnostic.measureStoryScoreScenes(track),raw:[...track.querySelectorAll('[data-project-card-item]')].map(i=>raw(i,track))};
  // Visible production-DOM diagnostic copy without React/measurement callbacks.
  const visibleRoot=root.cloneNode(true);
  root.replaceWith(visibleRoot);
  visibleRoot.dataset.projectionMode='horizontal-enhanced';
  const focusTrack=visibleRoot.querySelector('[data-motion-track]');
  focusTrack.style.transform='translateX(-16800px)';
  const item=focusTrack.querySelectorAll('[data-project-card-item]')[2];
  await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
  const beforeFocus=raw(item,focusTrack);
  item.querySelector('a').focus({preventScroll:true});
  const focusStart=raw(item,focusTrack);
  const transition=item.getAnimations().find(a=>a.transitionProperty==='transform');
  const frames=[];
  if(transition){transition.pause();for(const time of [0,1,90,180,360]){transition.currentTime=time;frames.push(raw(item,focusTrack));}}
  return {candidate,result,live,liveIdle,beforeFocus,focusStart,frames,mode:root.dataset.projectionMode,diagnosticForcedLiveMode:true};
 });
 await writeFile('/tmp/wflyer-visit3-classification/browser-v3.json',JSON.stringify({viewport:{width:1536,height:900},errors,...capture},null,2));
 console.log(JSON.stringify({candidateResult:capture.result,measurementEquality:JSON.stringify(capture.candidate.measurements)===JSON.stringify(capture.live.measurements),candidateRaw:capture.candidate.raw[2],liveRaw:capture.live.raw[2],focus:capture.frames[0]??capture.focusStart,errors},null,2));
}finally{await browser.close()}

