import {createRequire} from 'node:module';
import {readFile,writeFile} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const root=process.cwd(), dir='/tmp/wflyer-visit3-classification', req=createRequire(root+'/package.json');
const {build}=req(createRequire(req.resolve('vite')).resolve('esbuild'));
const sourceRoot=root+'/src/lib/story/score/';
const revisions={current:null,stage0:'40e6ae1a8996c53ed2ec372c47f16bc073d6cee9',phase9:'306ccb74da6c7bbf8f187e360c0776c571b5fc3d'};
const sourceHashes=[];
for(const [revision,ref] of Object.entries(revisions)){
 const bundled=await build({metafile:true,stdin:{contents:`export { buildBranchProjection, horizontalGeometry${revision==='current'?',buildBranchProjectionAttempt,requiredProjectShelfMinimumYs':''} } from '${sourceRoot}projection.ts';`,resolveDir:root,loader:'ts'},platform:'node',format:'cjs',bundle:true,outfile:`${dir}/${revision}.cjs`,alias:{'@':root+'/src'},plugins:[{name:'original-sources',setup(b){b.onLoad({filter:ref?/\/src\/.*\.ts$/:/\/(projection|organic-flowing)\.ts$/},async({path})=>{let s=ref?execFileSync('git',['show',`${ref}:${path.slice(root.length+1)}`],{cwd:root,encoding:'utf8'}):await readFile(path,'utf8');sourceHashes.push({revision,path:path.slice(root.length+1),ref,sha256:createHash('sha256').update(s).digest('hex')});if(path.endsWith('/projection.ts'))s+='\nexport {buildBranchProjection,horizontalGeometry'+(revision==='current'?',buildBranchProjectionAttempt,requiredProjectShelfMinimumYs':'')+'};';return {contents:s,loader:'ts',resolveDir:path.slice(0,path.lastIndexOf('/'))};});}}]});
 if(ref){for(const input of Object.keys(bundled.metafile.inputs).filter(x=>x.startsWith('src/')&&!x.endsWith('/projection.ts')&&!x.endsWith('/organic-flowing.ts'))){const live=await readFile(root+'/'+input);let prior;try{prior=execFileSync('git',['show',ref+':'+input],{cwd:root})}catch{prior=null}sourceHashes.push({revision,path:input,dependency:true,matchesHistorical:prior!==null&&live.equals(prior),sha256:createHash('sha256').update(live).digest('hex')});}}
}
const browser=JSON.parse(await readFile(dir+'/browser-v3.json','utf8'));
const m=browser.candidate.measurements, w=1536,h=900;
const cur=req(dir+'/current.cjs');
const original=cur.buildBranchProjectionAttempt('horizontal-enhanced','professional',w,h,m);
const mins=cur.requiredProjectShelfMinimumYs(original,m);
const records=[];
for(const revision of ['current','ablation','stage0','phase9']){
 const mod=revision==='ablation'?cur:req(dir+'/'+revision+'.cjs');
 const branch=(revision==='ablation'?mod.buildBranchProjectionAttempt:mod.buildBranchProjection)('horizontal-enhanced','professional',w,h,m);
 const geometry=mod.horizontalGeometry('professional',w,h,m,48,revision==='current'?mins:undefined);
 const ranges=geometry.notationRanges.filter(r=>r.chapterId==='professional-projects');
 const zone=branch.zones.filter(z=>z.chapterId==='professional-projects'&&z.kind==='notation-safe')[2];
 const range=ranges[2];
 const edges=branch.model.staff.lines.flatMap(line=>line.points.slice(1).map((b,i)=>({a:line.points[i],b,radius:line.thickness/2,id:line.id,startT:i/(line.points.length-1),endT:(i+1)/(line.points.length-1)})));
 records.push({revision,zone,range,minimumYs:revision==='current'?mins:null,knots:geometry.knots,shelfKnots:geometry.knots.slice(range.startSegmentIndex-1,range.endSegmentIndex+2),ranges,edges,samples:Array.from({length:101},(_,i)=>branch.path.pointAt(zone.startT+(zone.endT-zone.startT)*i/100)),eventCount:zone.eventCount});
}
const prior=JSON.parse(await readFile(root+'/openspec/changes/implement-scroll-driven-score-assembly-and-motion/stage-1-projects-interaction-lineage-diagnostics.json','utf8'));
const fixtures=JSON.parse(await readFile(root+'/tests/fixtures/story-score/stage1-batch2-measurements.json','utf8'));
const persistedPreSolComparison=fixtures.slice(0,3).map(f=>{const o=f.options,g=cur.horizontalGeometry('professional',o.viewportWidth,o.viewportHeight,o.sceneMeasurements,48),rr=g.notationRanges.filter(r=>r.chapterId==='professional-projects')[2],actual={visit:3,start:rr.startSegmentIndex,end:rr.endSegmentIndex,anchor:rr.projectVisit.anchor,firstPoint:g.knots[rr.startSegmentIndex-1],lastPoint:g.knots[rr.endSegmentIndex+1]},saved=prior.replays.find(r=>r.revision==='current'&&r.fixture===f.id).joins[2];return {fixture:f.id,saved,actual,equal:JSON.stringify(saved)===JSON.stringify(actual)};});
await writeFile(dir+'/replay.json',JSON.stringify({sourceHashes,records,persistedPreSolComparison},null,2));
console.log(records.map(r=>({revision:r.revision,anchor:r.range.projectVisit.anchor,range:[r.zone.startT,r.zone.endT],edges:r.edges.length,knots:r.shelfKnots,mins:r.minimumYs})));
